$ cat Depth.java
public class Depth {
    static int d = 0;
    static void plain() { d++; plain(); }
    static void withLocals() {
        d++;
        long a=1,b=2,c=3,e=4,f=5,g=6,h=7,i=8;
        withLocals();
        if (a+b+c+e+f+g+h+i == 0) System.out.print("");
    }
    public static void main(String[] x) {
        try { if (x[0].equals("plain")) plain(); else withLocals(); }
        catch (StackOverflowError so) { System.out.println(x[0] + " depth=" + d); }
    }
}

# --- 1) 이 머신의 기본 스택 크기 ---

$ java -XX:+PrintFlagsFinal -version | grep ThreadStackSize
intx CompilerThreadStackSize    = 2048
intx ThreadStackSize            = 2048
intx VMThreadStackSize          = 2048

# --- 2) 스택만 바꾼다 ---

$ java -Xss512k -cp out Depth plain     ->  plain depth=4210
$ java -Xss1m   -cp out Depth plain     ->  plain depth=19708
$ java -Xss2m   -cp out Depth plain     ->  plain depth=44965

# --- 3) 스택은 그대로, 프레임만 키운다 ---

$ java -Xss1m -cp out Depth plain       ->  plain  depth=20704
$ java -Xss1m -cp out Depth locals      ->  locals depth=11640

# long 8개를 더 얹었더니 깊이가 절반이 됐다.
# 스택 크기는 같다. 달라진 것은 프레임 하나의 크기뿐이다.
